    // Initialize Sheet URL for this unit
    const storageUrlKey = `sao_sheet_url_${selectedUnit.id}`;
    const storedUrl = localStorage.getItem(storageUrlKey);
    const urlToUse = storedUrl || selectedUnit.defaultSheetUrl;
