    initApp();

    const autoSyncInterval = setInterval(() => {
      if (navigator.onLine) syncData(false);
    }, 5 * 60 * 1000);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      clearInterval(autoSyncInterval);
