    setCheckoutCart([...checkoutCart, newItem]);

    // Reset item fields but keep borrower info
    setCheckoutMaterial('');
    setCheckoutReason('');
    setCheckoutType(MaterialType.OUTROS);
    setCheckoutImage('');
    if(fileInputRef.current) fileInputRef.current.value = "";
