      await sendMovementEmail(authState.user.bm, msgDutyOfficer, `Registro de Saída - ${subjectSuffix}`);

    } else {
      setSyncError(true);
      addNotification("Aviso: Dados salvos localmente, sync pendente.", "error");
    }

    setCheckoutCart([]);
