  }, [selectedUnit]);

  // Check firebase config status on load
  useEffect(() => {
    setIsFirebaseConfigured(!!auth && !!googleProvider);
  }, []);

  // Load selected unit from storage on mount
  useEffect(() => {
    const savedUnitId = localStorage.getItem('sao_selected_unit_id');
