            <button onClick={() => setShowInstructions(true)} className="absolute top-4 right-4 p-2.5 bg-white/10 hover:bg-white/20 rounded-xl backdrop-blur-sm transition-all text-white shadow-lg border border-white/10" title="Manual de Instruções"><BookOpen className="w-5 h-5" /></button>
            <img src="https://www.bombeiros.mg.gov.br/images/logo.png" alt="Logo CBMMG" className="w-24 mx-auto mb-6 drop-shadow-xl" />
