            ) : (
              // MAIN LOGIN SCREEN
              <>
                <button 
                  onClick={handleGoogleLogin} 
                  className={`w-full bg-white text-slate-600 font-bold py-3.5 rounded-xl shadow-md border border-slate-200 flex items-center justify-center gap-3 transition-all hover:bg-slate-50 active:scale-95 mb-6 ${!isFirebaseConfigured ? 'opacity-50 cursor-not-allowed' : ''}`}
                  disabled={!isFirebaseConfigured}
                >
                  <svg className="w-5 h-5" viewBox="0 0 24 24">
