import { Movement } from "./types";

// A chave de API agora fica segura dentro do Google Apps Script (Script Properties),
// e não mais exposta aqui no front-end.

export const getSmartSummary = async (movements: Movement[], sheetUrl: string) => {
  try {
    const pending = movements.filter(m => m.status === 'PENDENTE');

    // Preparar o contexto para enviar ao GAS
    const today = new Date().toISOString().split('T')[0];
    const contextList = pending.map(m => {
      const isOverdue = m.estimatedReturnDate && m.estimatedReturnDate < today;
      return `- ${m.rank} ${m.warName} (BM ${m.bm}): ${m.material}. Prev: ${m.estimatedReturnDate || 'N/A'} ${isOverdue ? '[ATRASADO]' : ''}`;
    }).join('\n');

    const prompt = `Analise a seguinte lista de materiais acautelados na SAO do 6º BBM e forneça um resumo executivo de prontidão operacional. 
      Identifique itens críticos (especialmente os atrasados) e sugira ações de controle. 
      Seja breve e militar.\n\nLista:\n${contextList}`;

    // Chama o GAS que atuará como Proxy para o Gemini
    // Isso protege sua API KEY e evita acesso direto do navegador
    const response = await fetch(sheetUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'text/plain;charset=utf-8' },
      body: JSON.stringify({
        action: 'callGemini',
        prompt: prompt,
        appSecret: "SAO_6BBM_SECURE_TOKEN_2024" // Token simples para validar a origem
      })
    });

    const text = await response.text();
    return text;

  } catch (error) {
    console.error("Erro ao solicitar análise via GAS:", error);
    return "Erro de conexão com o servidor de IA via Proxy Seguro.";
  }
};
